'use client'

import * as React from 'react'
import { useTranslations } from 'next-intl'
import { Loader2, Check } from 'lucide-react'

import { Button, Label } from '@ihui/ui-react'
import { useAuthStore, type AuthUser } from '@/stores/auth'
import { fetchApi } from '@/lib/api'
import { Alert } from '@/components/feedback'
import { AgreementCheckbox } from '@/components/auth/AgreementCheckbox'
import { phoneSchema, type TokenResult } from './login-schemas'
import { OtpInput } from './OtpInput'
import { AccountHistoryInput } from './AccountHistoryInput'
import { saveLoginHistory } from '@/lib/remember-credentials'
import { loadLocalLoginPrefs, saveLocalLoginPrefs } from '@/lib/login-preferences'

interface PhoneCodeLoginFormProps {
  active: boolean
  onSuccess?: () => void
  agreed?: boolean
  onAgreedChange?: (v: boolean) => void
  onRequireAgree?: () => void
  showAgreeErr?: boolean
}

export function PhoneCodeLoginForm({
  active,
  onSuccess,
  agreed = true,
  onAgreedChange,
  onRequireAgree,
  showAgreeErr,
}: PhoneCodeLoginFormProps) {
  const t = useTranslations('auth')
  const setToken = useAuthStore((s) => s.setToken)
  const setUser = useAuthStore((s) => s.setUser)

  const [phone, setPhone] = React.useState('')
  const [code, setCode] = React.useState('')
  const [err, setErr] = React.useState<string | null>(null)
  const [countdown, setCountdown] = React.useState(0)
  const [sending, setSending] = React.useState(false)
  const [submitting, setSubmitting] = React.useState(false)
  const [autoLogin, setAutoLogin] = React.useState(loadLocalLoginPrefs().autoLogin)
  // 2026-07-22 P1 鲁棒性加固:interval 存 ref,unmount 时清理防内存泄漏
  const countdownTimerRef = React.useRef<ReturnType<typeof setInterval> | null>(null)

  React.useEffect(() => {
    if (!active) setErr(null)
  }, [active])

  React.useEffect(() => {
    return () => {
      if (countdownTimerRef.current) clearInterval(countdownTimerRef.current)
    }
  }, [])

  const startCountdown = () => {
    setCountdown(60)
    if (countdownTimerRef.current) clearInterval(countdownTimerRef.current)
    countdownTimerRef.current = setInterval(() => {
      setCountdown((c) => {
        if (c <= 1) {
          if (countdownTimerRef.current) {
            clearInterval(countdownTimerRef.current)
            countdownTimerRef.current = null
          }
          return 0
        }
        return c - 1
      })
    }, 1000)
  }

  const onSendCode = async () => {
    setErr(null)
    const parsed = phoneSchema.safeParse(phone)
    if (!parsed.success) {
      setErr(t('invalidPhone'))
      return
    }
    setSending(true)
    try {
      const result = await fetchApi<{ sent: boolean }>('/api/auth/sms/code', {
        method: 'POST',
        body: JSON.stringify({ phone }),
      })
      if (!result.success) {
        setErr(result.error || t('loginFailed'))
        return
      }
      startCountdown()
    } catch {
      setErr(t('loginFailed'))
    } finally {
      setSending(false)
    }
  }

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setErr(null)
    if (!agreed) {
      onRequireAgree?.()
      return
    }
    const pp = phoneSchema.safeParse(phone)
    if (!pp.success) {
      setErr(t('invalidPhone'))
      return
    }
    if (code.length !== 6) {
      setErr(t('enterCode'))
      return
    }
    setSubmitting(true)
    try {
      const result = await fetchApi<TokenResult>('/api/auth/login/phone-code', {
        method: 'POST',
        body: JSON.stringify({ phone, code }),
      })
      if (!result.success || !result.data?.accessToken) {
        setErr(result.error || t('loginFailed'))
        return
      }
      setToken(result.data.accessToken, result.data.refreshToken)
      if (result.data.userId) {
        setUser({ id: result.data.userId, nickname: '' })
        void fetchApi<{ user: AuthUser }>('/api/auth/me').then((r) => {
          if (r.success) setUser(r.data.user)
        })
      }
      saveLoginHistory(phone)
      onSuccess?.()
    } catch {
      setErr(t('loginFailed'))
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <form onSubmit={onSubmit} className="space-y-4 pt-2">
      {err && <Alert variant="danger" description={err} />}
      <div className="space-y-1.5">
        <Label htmlFor="phone">{t('phone')}</Label>
        <AccountHistoryInput
          id="phone"
          type="tel"
          autoComplete="tel"
          placeholder={t('phonePlaceholder')}
          className="h-10"
          value={phone}
          onChange={setPhone}
          active={active}
        />
      </div>
      <div className="space-y-1.5">
        <Label>{t('code')}</Label>
        <div className="flex items-center gap-2">
          <OtpInput
            value={code}
            onChange={setCode}
            disabled={submitting}
            aria-label={t('code')}
            className="flex-1"
          />
          <Button
            type="button"
            variant="outline"
            className="h-11 shrink-0 px-3 text-sm"
            disabled={sending || countdown > 0}
            onClick={onSendCode}
          >
            {countdown > 0 ? t('resendCode', { seconds: countdown }) : t('getVerificationCode')}
          </Button>
        </div>
      </div>
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1">
          <AgreementCheckbox
            checked={agreed}
            onChange={(v) => onAgreedChange?.(v)}
            error={showAgreeErr && !agreed}
          />
          {showAgreeErr && !agreed && <p className="text-xs text-destructive">{t('agreeRequired')}</p>}
        </div>
        <MiniCheckbox
          checked={autoLogin}
          onChange={(v) => {
            setAutoLogin(v)
            saveLocalLoginPrefs({ autoLogin: v })
          }}
          label={t('autoLogin')}
        />
      </div>
      <Button type="submit" className="h-10 w-full" disabled={submitting}>
        {submitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
        {t('loginBtn')}
      </Button>
    </form>
  )
}

function MiniCheckbox({ checked, onChange, label }: { checked: boolean; onChange: (v: boolean) => void; label: string }) {
  return (
    <label className="group flex cursor-pointer items-center gap-2 select-none">
      <span
        onClick={(e) => { e.preventDefault(); onChange(!checked) }}
        className={[
          'flex h-4 w-4 shrink-0 items-center justify-center rounded-[4px] border transition-all duration-200',
          checked ? 'border-primary bg-primary text-primary-foreground' : 'border-input bg-background group-hover:border-foreground/60',
        ].join(' ')}
        role="checkbox"
        aria-checked={checked}
        tabIndex={0}
        onKeyDown={(e) => { if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); onChange(!checked) } }}
      >
        {checked && <Check className="h-3 w-3" strokeWidth={3} />}
      </span>
      <input type="checkbox" className="sr-only" tabIndex={-1} checked={checked} onChange={(e) => onChange(e.target.checked)} />
      <span className="text-xs leading-5 text-muted-foreground">{label}</span>
    </label>
  )
}
